/// <summary>
/// AVA
/// </summary>
[ExtensionOf(classStr(LedgerJournalEngine))]
final class AVALedgerJournalEngineCls_Extension
{
    private AVARepostPeriod                    oldRepostPeriod;

}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "_ledgerJournalTrans">LedgerJournalTrans</param>
/// <param name = "_ledgerJournalTrans_Project">LedgerJournalTrans_Project</param>
/// <param name = "_ledgerJournalTransDS">FormDataSource</param>
public void AVARepostPeriodeCreate(LedgerJournalTrans              _ledgerJournalTrans,
                         LedgerJournalTrans_Project      _ledgerJournalTrans_Project,
                         FormDataSource                  _ledgerJournalTransDS = null)
{
    AVALedgerJournalTransRepost     LedgerJournalTransRepost;
    LedgerJournalTrans              sourceLedgerJournalTrans;
    TaxAmount                       taxAmount;

    if (_ledgerJournalTrans.AVARepostPeriod &&
    _ledgerJournalTrans.AVARepostPeriod != oldRepostPeriod)
    {
        sourceLedgerJournalTrans.data(_ledgerJournalTrans);
        LedgerJournalTransRepost = new AVALedgerJournalTransRepost();
        LedgerJournalTransRepost.parmLedgerJournalTrans(sourceLedgerJournalTrans);
        LedgerJournalTransRepost.parmSourceLedgerJournalTrans_Project(_ledgerJournalTrans_Project);
        taxAmount   = this.parmActualTax();
        if (_ledgerJournalTrans.ledgerJournalTable().LedgerJournalInclTax && taxAmount == 0)
        {
            taxAmount = this.correctedTaxAmount(_ledgerJournalTrans);
        }
        //LedgerJournalTransRepost.parmTaxAmount(this.parmActualTax());
        LedgerJournalTransRepost.parmTaxAmount(taxAmount);
        //LedgerJournalTransRepost.run();
        LedgerJournalTransRepost.runOperation();

        if (_ledgerJournalTransDS)
        {
            _ledgerJournalTransDS.research(true);
        }
    }
}

public AVARepostPeriod parmoldrepostPeriod(AVARepostPeriod _oldRepostPeriod = oldrepostPeriod)
{
    oldRepostPeriod = _oldRepostPeriod;

    return oldRepostPeriod;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_ledgerJournalTrans">LedgerJournalTrans</param>
/// <param name = "_ledgerJournalTrans_Project">LedgerJournalTrans_Project</param>
/// <param name = "_ledgerJournalTrans_RCash">LedgerJournalTrans_RCash</param>
public void preWrite(LedgerJournalTrans _ledgerJournalTrans, LedgerJournalTrans_Project _ledgerJournalTrans_Project, LedgerJournalTrans_RCash   _ledgerJournalTrans_RCash)
{
    this.parmoldrepostPeriod(_ledgerJournalTrans.orig().AVARepostPeriod);

    next preWrite(_ledgerJournalTrans, _ledgerJournalTrans_Project, _ledgerJournalTrans_RCash);
}

public void write(LedgerJournalTrans            _ledgerJournalTrans,
                  boolean                       _updateCashDisc,
                  LedgerJournalTrans_Asset      _ledgerJournalTrans_Asset,
                  LedgerJournalTrans_RDeferrals _ledgerJournalTrans_RDeferrals,
                  LedgerJournalTrans_RCash      _ledgerJournalTrans_RCash)
{
    next write(_ledgerJournalTrans, _updateCashDisc, _ledgerJournalTrans_Asset, _ledgerJournalTrans_RDeferrals, _ledgerJournalTrans_RCash);

    this.AVARepostPeriodeCreate(_ledgerJournalTrans, ledgerJournalTrans_Project, ledgerJournalTrans_ds);
}
